r[data-v-04e5fd3e]{overflow-x:auto;max-height:480px;overflow-y:auto}.dialogue-table[data-v-04e5fd3e]{width:100%;border-collapse:collapse;font-size:0.82rem;text-align:left}.dialogue-table th[data-v-04e5fd3e]{position:sticky;top:0;background:var(--surface);z-index:5;padding:10px 10px;font-family:var(--font-mono);font-size:0.72rem;font-weight:600;color:var(--muted-ink);text-transform:uppercase;border-bottom:1px solid var(--rule)}.dialogue-table td[data-v-04e5fd3e]{padding:8px 10px;border-bottom:1px solid var(--rule);vertical-align:middle}.dialogue-table tr[data-v-04e5fd3e]:hover{background:rgba(245,243,240,0.5)}.dialogue-table tr.row-synthesizing[data-v-04e5fd3e]{background:rgba(184,134,11,0.08);border-left:3px solid var(--gold)}.dialogue-table tr.row-done[data-v-04e5fd3e]{border-left:3px solid var(--success)}.dialogue-table tr.row-failed[data-v-04e5fd3e]{border-left:3px solid var(--danger)}.field-control.sm[data-v-04e5fd3e]{min-height:32px;padding:5px 8px;font-size:0.8rem;border-radius:6px}.speed-select[data-v-04e5fd3e]{width:72px}.line-clamp[data-v-04e5fd3e]{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:0.78rem;line-height:1.4;color:var(--muted-ink)}.ja-cell[data-v-04e5fd3e]{position:relative}.ja-badge[data-v-04e5fd3e]{position:absolute;top:4px;right:6px;font-family:var(--font-mono);font-size:0.65rem;background:rgba(184,134,11,0.15);color:var(--gold);border:1px solid var(--gold);border-radius:4px;padding:1px 4px}.emotion-badge[data-v-04e5fd3e]{display:inline-flex;align-items:center;gap:4px;padding:2px 7px;border-radius:4px;border:1px solid rgba(184,134,11,0.3);background:rgba(184,134,11,0.08);color:var(--gold);font-size:0.75rem}.status-badge[data-v-04e5fd3e]{display:inline-block;padding:2px 6px;border-radius:4px;font-family:var(--font-mono);font-size:0.7rem;border:1px solid var(--rule)}.status-badge.synthesizing[data-v-04e5fd3e]{border-color:var(--gold);color:var(--gold);background:rgba(184,134,11,0.1);animation:pulseS